// ExtensionForOpcode returns the extension that owns an opcode, or "" for core blocks.
func ExtensionForOpcode(opcode string) string {
	switch {
	case strings.HasPrefix(opcode, "pen_"):
		return "pen"
	case strings.HasPrefix(opcode, "music_"):
		return "music"
	case strings.HasPrefix(opcode, "text2speech_"):
		return "text2speech"
	}
	return ""
}
